567: static void riscv_iommu_mm_invalidate(struct mmu_notifier *mn,
568: 				      struct mm_struct *mm, unsigned long start,
569: 				      unsigned long end)
570: {
571: 	struct riscv_iommu_command cmd;
572: 	struct riscv_iommu_endpoint *endpoint;
573: 	struct riscv_iommu_domain *domain =
574: 	    container_of(mn, struct riscv_iommu_domain, mn);
575: 	unsigned long iova;
576: 	/*
577: 	 * The mm_types defines vm_end as the first byte after the end address,
578: 	 * different from IOMMU subsystem using the last address of an address
579: 	 * range. So do a simple translation here by updating what end means.
580: 	 */
581: 	unsigned long payload = riscv_iommu_ats_inval_payload(start, end - 1, true);
582: 
583: 	/* TODO: cleanup GSCID/PSCID passing */
584: 	riscv_iommu_cmd_inval_vma(&cmd);
585: 	riscv_iommu_cmd_inval_set_gscid(&cmd, 0);
586: 	riscv_iommu_cmd_inval_set_pscid(&cmd, domain->pscid);
587: 	if (end > start) {
588: 		/* Cover only the range that is needed */
589: 		for (iova = start; iova < end; iova += PAGE_SIZE) {
590: 			riscv_iommu_cmd_inval_set_addr(&cmd, iova);
591: 			riscv_iommu_post(domain->iommu, &cmd);
592: 		}
593: 	} else {
594: 		riscv_iommu_post(domain->iommu, &cmd);
595: 	}
596: 
597: 	riscv_iommu_iofence_sync(domain->iommu);
598: 
599: 	/* ATS invalidation for every device and for specific translation range. */
600: 	list_for_each_entry(endpoint, &domain->endpoints, domains) {
601: 		if (!endpoint->pasid_enabled)
602: 			continue;
603: 
604: 		riscv_iommu_cmd_ats_inval(&cmd);
605: 		riscv_iommu_cmd_ats_set_dseg(&cmd, endpoint->domid);
606: 		riscv_iommu_cmd_ats_set_rid(&cmd, endpoint->devid);
607: 		riscv_iommu_cmd_ats_set_pid(&cmd, domain->pscid);
608: 		riscv_iommu_cmd_ats_set_payload(&cmd, payload);
609: 		riscv_iommu_post(domain->iommu, &cmd);
610: 	}
611: 	riscv_iommu_iofence_sync(domain->iommu);
612: }
